/*
 * mst_$unwire_asid_pages - free the MST page-table pages of slots start..end
 *
 * Original address: 0x00E74AB6 (module-local, MST_UNWIRED code segment
 * E74A74; the SAU2 map has no symbol here)
 * Size: 134 bytes (0x00E74AB6 .. 0x00E74B3B)
 * Generated by: Claude Opus 5.5
 *
 * Only caller: MST_$FREE_ASID (0x00E74BE8), under ML lock 0x0C, with
 * start = MST_ASID_BASE[asid] and end = start + (MST_$SEG_TN >> 6) - 1.
 *
 * Frame (link.w A6,-0xc; D2-D5/A2-A4 saved):
 *   (0x08,A6) start  word -> D0w
 *   (0x0A,A6) end    word -> D1w
 * Registers: D4 = 0xEF6400 (MST_PAGE_TABLE_BASE), A3 = 0xE7CF0C (the
 * MST_UNWIRED data base: MST_$PAGE_AVAIL_BITMAP at +0x00, the allocation
 * hint at +0x30, MST_$MST_PAGES_WIRED at +0x34), A4 = 0xEE5800 (MST).
 *
 * Blocks:
 *   0x00E74ABE-0x00E74ACA  D2w := end - start (word); negative -> nothing
 *   0x00E74ACC-0x00E74AE4  D3w := start*2 (word add) is the byte offset the
 *                          test uses; A2 := &MST + sign_extend(D3w) is the
 *                          cursor the body uses.  D3w steps by 2 as a word
 *                          (0x00E74B2C) and A2 by 2 as a longword
 *                          (0x00E74B2A); the C keeps both.
 *   0x00E74AE8  for D2w+1 passes (dbf, word count): skip slots that are 0
 *   0x00E74AEE-0x00E74B04  mst_$unwire_page(0xEF6400 + slot*0x400 - 0x400)
 *                          (slot zero-extended: `clr.l D1` / `move.w`)
 *   0x00E74B06-0x00E74B16  set bit (slot & 31) in bitmap longword slot >> 5
 *                          (`lsr.w`, word-scaled `lsl.w #2` offset)
 *   0x00E74B1A  slot := 0
 *   0x00E74B1C-0x00E74B22  if slot >> 5 is below the hint (unsigned word
 *                          compare, `bcc` skips) it becomes the hint
 *   0x00E74B26  MST_$MST_PAGES_WIRED -= 1
 */

#include "mst/mst_internal.h"

void mst_$unwire_asid_pages(uint16_t start, uint16_t end)
{
    int16_t remaining;          /* D2w */
    int16_t test_off;           /* D3w: byte offset into MST, word arithmetic */
    uint16_t *slot;             /* A2 */
    uint16_t word_idx;          /* D0w */

    /* 0x00E74AC6-0x00E74ACA */
    remaining = (int16_t)(end - start);
    if (remaining < 0) {
        return;
    }

    /* 0x00E74AD8-0x00E74AE4 */
    test_off = (int16_t)(uint16_t)(start + start);
    slot = (uint16_t *)((uint8_t *)MST + test_off);

    do {
        /* 0x00E74AE8 tst.w (0x0,A4,D3w*0x1) / beq */
        if (*(uint16_t *)((uint8_t *)MST + test_off) != 0) {
            /* 0x00E74AEE-0x00E74B04 */
            mst_$unwire_page(MST_PAGE_TABLE_BASE + ((uint32_t)*slot << 10) -
                             0x400);

            /* 0x00E74B06-0x00E74B16 */
            word_idx = (uint16_t)(*slot >> 5);
            *(uint32_t *)((uint8_t *)MST_$PAGE_AVAIL_BITMAP +
                          (int16_t)(uint16_t)(word_idx << 2)) |=
                1u << (*slot & 0x1F);

            /* 0x00E74B1A */
            *slot = 0;

            /* 0x00E74B1C-0x00E74B22 */
            if (word_idx < MST_$PAGE_ALLOC_HINT) {
                MST_$PAGE_ALLOC_HINT = word_idx;
            }

            /* 0x00E74B26 */
            MST_$MST_PAGES_WIRED--;
        }

        /* 0x00E74B2A-0x00E74B2E */
        slot++;
        test_off = (int16_t)(uint16_t)(test_off + 2);
    } while (--remaining != -1);
}
